const d = $input.first().json;

const studentName = (d['Student Name'] || d.studentName || '').toString().trim();
const studentEmail = (d['Student Email'] || d.studentEmail || '').toString().trim();
const topic = (d['Assignment Topic'] || d.topic || '').toString().trim();
const subject = (d['Course / Subject'] || d.subject || '').toString().trim();
const academicLevel = (d['Academic Level'] || d.academicLevel || '').toString().trim();
const instructions = (d['Additional Instructions'] || d.instructions || '').toString().trim();

if (!studentName || !studentEmail || !topic || !subject || !academicLevel) {
  return [{ json: { success: false, message: 'Please complete all required fields.' } }];
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(studentEmail)) {
  return [{ json: { success: false, message: 'Please provide a valid email address.' } }];
}

return [{
  json: {
    success: true,
    studentName,
    studentEmail,
    topic,
    subject,
    academicLevel,
    instructions
  }
}];

parameters.text:
=You are an expert academic assignment writer. Generate a complete, original, well-structured academic assignment.

Student Name: {{ $json.studentName }}
Topic: {{ $json.topic }}
Subject / Course: {{ $json.subject }}
Academic Level: {{ $json.academicLevel }}
Additional Instructions: {{ $json.instructions || 'None' }}

Return ONLY a valid JSON object with exactly this structure (no markdown, no code fences, no extra text):
{
  "title": "",
  "studentName": "",
  "subject": "",
  "academicLevel": "",
  "introduction": "",
  "sections": [
    { "heading": "", "content": "" }
  ],
  "conclusion": "",
  "references": []
}

Include these sections (as items inside the sections array):
- Background / Definition
- Main Concepts
- Detailed Explanation
- Important Subtopics
- Advantages
- Disadvantages
- Applications / Real-world Examples
- Challenges
- Future Scope

Make the content appropriate for the academic level, educational, professional, detailed, and grammatically correct. Do not invent fake academic citations.

