const prev = $input.first().json;

if (prev.success === false) {
  return [{ json: prev }];
}

let raw = '';
if (typeof prev.text === 'string') raw = prev.text;
else if (prev.response) raw = typeof prev.response === 'string' ? prev.response : JSON.stringify(prev.response);
else if (prev.output) raw = typeof prev.output === 'string' ? prev.output : JSON.stringify(prev.output);
else raw = JSON.stringify(prev);

raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { success: false, message: 'AI returned invalid assignment data.' } }];
}

if (!parsed.title || !parsed.introduction || !Array.isArray(parsed.sections) || !parsed.conclusion) {
  return [{ json: { success: false, message: 'AI returned invalid assignment data.' } }];
}

if (!Array.isArray(parsed.references)) parsed.references = [];

const v = $('Validate Form Data').item.json;

return [{
  json: {
    success: true,
    title: parsed.title,
    studentName: parsed.studentName || v.studentName,
    subject: parsed.subject || v.subject,
    academicLevel: parsed.academicLevel || v.academicLevel,
    introduction: parsed.introduction,
    sections: parsed.sections,
    conclusion: parsed.conclusion,
    references: parsed.references,
    topic: v.topic,
    studentEmail: v.studentEmail
  }
}];

const data = $input.first().json;

if (data.success === false) {
  return [{ json: data }];
}

function esc(s) {
  if (s == null) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const title = esc(data.title);
const studentName = esc(data.studentName);
const subject = esc(data.subject);
const level = esc(data.academicLevel);
const intro = esc(data.introduction).replace(/\n+/g, '</p><p>');
const conclusion = esc(data.conclusion).replace(/\n+/g, '</p><p>');

let sectionsHtml = '';
(data.sections || []).forEach((sec, i) => {
  const h = esc(sec.heading || `Section ${i+1}`);
  const c = esc(sec.content || '').replace(/\n+/g, '</p><p>');
  sectionsHtml += `<section class="section"><h2>${i+1}. ${h}</h2><p>${c}</p></section>`;
});

let refs = '<p>No references listed.</p>';
if (Array.isArray(data.references) && data.references.length) {
  refs = '<ol class="references">' + data.references.map(r => `<li>${esc(r)}</li>`).join('') + '</ol>';
}

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>${title}</title>
<style>
@page { size: A4; margin: 20mm; }
* { box-sizing: border-box; }
body { font-family: "Times New Roman", Times, Georgia, serif; font-size: 12pt; line-height: 1.65; color: #1a1a1a; margin: 0; }
.page { max-width: 210mm; margin: 0 auto; }
header { text-align: center; border-bottom: 2.5px solid #1a365d; padding-bottom: 14px; margin-bottom: 24px; }
header h1 { font-size: 20pt; margin: 0 0 10px 0; color: #1a365d; }
.meta { font-size: 10.5pt; color: #4a5568; line-height: 1.5; }
h2 { font-size: 13.5pt; color: #1a365d; margin: 20px 0 8px 0; padding-bottom: 3px; border-bottom: 1px solid #cbd5e0; }
p { margin: 0 0 11px 0; text-align: justify; }
.section { margin-bottom: 6px; }
.conclusion { margin-top: 26px; padding-top: 12px; border-top: 1px solid #cbd5e0; }
.references { margin-top: 8px; padding-left: 22px; }
.references li { margin-bottom: 5px; }
footer { margin-top: 30px; padding-top: 10px; border-top: 1px solid #e2e8f0; font-size: 9pt; color: #718096; text-align: center; }
</style>
</head>
<body>
<div class="page">
<header>
  <h1>${title}</h1>
  <div class="meta">
    Student: ${studentName}<br>
    Subject: ${subject}<br>
    Academic Level: ${level}
  </div>
</header>
<section><h2>Introduction</h2><p>${intro}</p></section>
${sectionsHtml}
<section class="conclusion"><h2>Conclusion</h2><p>${conclusion}</p></section>
<section><h2>References</h2>${refs}</section>
<footer>Generated by AI Assignment Generator · ${new Date().toISOString().slice(0,10)}</footer>
</div>
</body>
</html>`;

return [{
  json: {
    success: true,
    html,
    studentName: data.studentName,
    studentEmail: data.studentEmail,
    topic: data.topic,
    title: data.title
  }
}];

const pdfNode = $input.first();
const htmlNode = $('Generate Assignment HTML').item.json;
const validateNode = $('Validate Form Data').item.json;

if (htmlNode.success === false || validateNode.success === false) {
  return [{ json: { success: false, message: htmlNode.message || validateNode.message || 'Unable to generate the assignment.' } }];
}

if (!pdfNode.json.url && !pdfNode.binary) {
  return [{ json: { success: false, message: 'Unable to generate the assignment PDF.' } }];
}

return [{
  json: {
    success: true,
    studentName: htmlNode.studentName,
    studentEmail: htmlNode.studentEmail,
    topic: htmlNode.topic,
    title: htmlNode.title,
    emailSubject: `Your AI-Generated Assignment: ${htmlNode.topic}`,
    emailBody: `Hello ${htmlNode.studentName},\n\nYour assignment on "${htmlNode.topic}" has been successfully generated.\n\nPlease find the PDF attached to this email.\n\nRegards,\nAI Assignment Generator`
  },
  binary: pdfNode.binary
}];
